const crystals=[['紫水晶','火','紫色','#9e81be','沉静思考','通透紫色，带自然色带'],['粉晶','火','粉色','#d9a6ad','温柔表达','柔雾粉色，半透明质感'],['白水晶','金','白色','#d4dfdc','清晰与留白','清透无色，内部冰裂纹'],['黑曜石','水','黑色','#30343b','边界与安定','深黑玻璃光泽'],['红玛瑙','火','红色','#b65d49','行动与勇气','深红至橙红，细腻色带'],['虎眼石','土','棕色','#b08b4c','坚定与专注','金棕色，流动猫眼光带'],['海蓝宝','水','蓝色','#9bcbd5','平和沟通','浅海蓝色，通透柔润'],['东陵玉','木','绿色','#69a287','生长与开放','柔和绿色，细小闪光颗粒'],['黄水晶','土','黄色','#d4b15d','自信与主动','浅黄到蜜金，通透明亮'],['茶晶','土','棕色','#837568','沉稳与秩序','烟茶色透明晶体'],['青金石','水','蓝色','#445c9a','真实表达','深蓝底色，金色星点'],['月光石','金','白色','#c1d1db','觉察与柔和','乳白底色，蓝色晕彩'],['石榴石','火','红色','#823c50','热忱与坚持','深酒红色，光下透红'],['草莓晶','火','粉色','#c7838c','连接与善意','淡粉色，细密红色包裹体'],['萤石','木','绿色','#8da898','好奇与创造','紫绿交织，透明色带'],['白松石','金','白色','#d1d5cd','简洁与从容','白色底，灰色网状纹理（howlite）']].map((x,id)=>({id,name:x[0],element:x[1],color:x[2],hex:x[3],meaning:x[4],texture:x[5]}));
const questions=[['在忙碌的一天结束后，你更想……',['一个人安静待着，慢慢恢复能量','找熟悉的人聊聊天，分享今天']],['面对一个新机会，你通常会……',['先收集信息，想清楚再行动','先迈出一步，在尝试中寻找答案']],['做重要决定时，你更在意……',['是否符合逻辑，结果是否可靠','自己的感受，以及对人的影响']],['面对突然改变的计划，你会……',['希望尽快重新安排，找回节奏','顺势调整，说不定有新的发现']],['在人际关系里，你更希望……',['保留自己的空间和边界','建立更深的理解与连接']],['此刻，你最想提醒自己的是……',['放慢一点，给自己一些余地','勇敢一点，把想法变成行动']],['你更容易被哪种风格吸引？',['安静克制，低饱和的配色','鲜明有趣，有一抹亮色']],['接下来的一段时间，你希望……',['专注内在，建立稳定的日常','向外探索，迎接新的可能']]];
const state={view:'quiz',q:0,answers:Array(8).fill(null),birth:{date:'',time:'12:00',unknown:false,wrist:16,size:8},chart:null,recipe:[{id:0,n:10},{id:3,n:6},{id:2,n:4}],result:false};
const $=s=>document.querySelector(s);const beadStyle=id=>`background-position:${id%4*100/3}% ${Math.floor(id/4)*100/3}%`;const bead=id=>`<span class="bead" style="${beadStyle(id)}"></span>`;
function renderQuiz(){const q=questions[state.q];$('#panel').innerHTML=`<div class="panel-head"><span>性格探索</span><span>${String(state.q+1).padStart(2,'0')} / 08 · 约 2 分钟</span></div><div class="progress"><div style="width:${(state.q+1)/8*100}%"></div></div><p class="question-kicker">${['能量来源','行动方式','决策偏好','生活节奏','人际边界','当下心愿','审美偏好','未来期待'][state.q]}</p><h2>${q[0]}</h2><p class="muted">没有标准答案，选择更接近此刻的自己。</p><div class="answers">${q[1].map((a,i)=>`<button class="answer ${state.answers[state.q]===i?'selected':''}" data-answer="${i}" aria-pressed="${state.answers[state.q]===i}"><i>${i?'B':'A'}</i><span>${a}</span></button>`).join('')}</div><div class="actions"><button class="secondary" id="prev" ${state.q===0?'disabled':''}>上一题</button><button class="primary" id="next" ${state.answers[state.q]===null?'disabled':''}>${state.q===7?'继续 · 东方命盘':'下一题'} →</button></div><p class="fine">你的选择与出生信息仅在当前页面计算，不上传服务器。</p>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{state.answers[state.q]=+b.dataset.answer;state.result=false;renderQuiz()});$('#prev').onclick=()=>{state.q--;renderQuiz()};$('#next').onclick=()=>{if(state.q<7){state.q++;renderQuiz()}else show('birth')};}
function show(view){if(view==='result'&&!state.result){if(state.answers.includes(null)){state.q=state.answers.indexOf(null);view='quiz'}else view='birth'}state.view=view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='quiz')renderQuiz();else if(view==='birth')renderBirth();else renderResult()}
function renderBirth(){$('#panel').innerHTML=`<p class="question-kicker">02 / 东方命盘</p><h2>记录你与世界相遇的时刻。</h2><p class="muted">以公历、北京时间（UTC+8）排盘。暂不校正真太阳时；海外出生请先换算北京时间。</p><form id="birthForm"><label for="date">出生日期 · 公历</label><input required id="date" type="date" min="1901-01-01" max="${new Date().toISOString().slice(0,10)}" value="${state.birth.date}"><label for="time">出生时间 · 北京时间</label><input id="time" type="time" value="${state.birth.time}" ${state.birth.unknown?'disabled':''}><label class="check"><input id="unknown" type="checkbox" ${state.birth.unknown?'checked':''}> 不确定时辰（仅分析前三柱）</label><div class="row"><div><label for="wrist">手围 · cm</label><input id="wrist" type="number" min="12" max="23" step="0.5" required value="${state.birth.wrist}"></div><div><label for="size">珠径 · mm</label><select id="size">${[6,8,10,12].map(s=>`<option ${s===state.birth.size?'selected':''}>${s}</option>`).join('')}</select></div></div><p class="fine">数量按手围 + 0.5 cm 松量估算。实物尺寸还需根据珠孔、弹力线与佩戴松紧调整。</p><p id="formError" class="error" role="alert"></p><div class="actions"><button type="button" class="secondary" id="backQuiz">返回问卷</button><button class="primary" type="submit">生成我的专属手串 ↗</button></div></form>`;$('#unknown').onchange=e=>$('#time').disabled=e.target.checked;$('#backQuiz').onclick=()=>{saveBirth();show('quiz')};$('#birthForm').onsubmit=e=>{e.preventDefault();saveBirth();if(state.answers.includes(null)){$('#formError').textContent='请先完成全部 8 道性格问题。';return}try{generate();show('result')}catch(err){$('#formError').textContent='排盘暂未完成，请检查出生日期和时间后重试。'}};}
function saveBirth(){state.birth={date:$('#date').value,time:$('#time').value||'12:00',unknown:$('#unknown').checked,wrist:+$('#wrist').value,size:+$('#size').value}}
function generate(){const b=state.birth;const [y,m,d]=b.date.split('-').map(Number);const [h,mi]=b.time.split(':').map(Number);const ec=Solar.fromYmdHms(y,m,d,b.unknown?12:h,mi,0).getLunar().getEightChar();ec.setSect(2);const pillars=[ec.getYear(),ec.getMonth(),ec.getDay(),b.unknown?'—':ec.getTime()];const wx=[ec.getYearWuXing(),ec.getMonthWuXing(),ec.getDayWuXing(),b.unknown?'':ec.getTimeWuXing()];const counts=Object.fromEntries(['木','火','土','金','水'].map(x=>[x,wx.join('').split(x).length-1]));const least=Object.keys(counts).sort((a,b)=>counts[a]-counts[b])[0];state.chart={pillars,counts,least};const a=state.answers;let primary=a[5]===0?(a[0]===0?0:6):(a[2]===0?5:4);let support=({'木':7,'火':12,'土':8,'金':11,'水':3})[least];if(support===primary)support=2;let accent=a[4]===0?3:1;if(accent===support||accent===primary)accent=2;const total=Math.round((b.wrist*10+5)/b.size);let p=Math.round(total*.5),s=Math.round(total*.3);state.recipe=[{id:primary,n:p},{id:support,n:s},{id:accent,n:total-p-s}];state.result=true;updatePreview();}
function renderResult(){const a=state.answers,c=state.chart;const traits=[a[0]?'从交流中充电':'享受独处',a[1]?'敢于尝试':'审慎思考',a[4]?'重视连接':'重视边界'];const reasons=[`你在问卷中选择「${questions[5][1][a[5]]}」。用${crystals[state.recipe[0].id].meaning}作为主调，让占比约一半的主石成为日常提醒。`,`四柱表层五行中「${c.least}」数量较少。依本产品的颜色映射加入对应珠材，以约三成比例构成视觉呼应；这不是喜用神判断。`,`你在人际关系中更偏向「${questions[4][1][a[4]]}」。以${crystals[state.recipe[2].id].meaning}的寓意做点缀，并用${crystals[state.recipe[2].id].color}形成层次。`];$('#panel').innerHTML=`<p class="question-kicker">03 / 为此刻的你而配</p><h2>${a[5]?'把勇气，戴在手腕上。':'在自己的节奏里，发光。'}</h2><div class="traits">${traits.map(t=>`<span>${t}</span>`).join('')}</div><div class="pillars">${c.pillars.map((p,i)=>`<div class="pillar"><small>${['年柱','月柱','日柱','时柱'][i]}</small><b>${p}</b></div>`).join('')}</div><p class="fine">表层五行：${Object.entries(c.counts).map(([k,v])=>`${k} ${v}`).join(' · ')}<br>节气定年月柱，日柱以午夜换日。仅计天干与地支本气，不含藏干、旺衰或喜用神分析${state.birth.unknown?'；时辰未知，未纳入时柱':''}。</p>${state.recipe.map((r,i)=>`<div class="reason">${bead(r.id)}<div><h3>${crystals[r.id].name} <strong>× ${r.n} 颗</strong> <small>· ${['主石','辅石','点缀'][i]}</small></h3><p>${reasons[i]}</p></div></div>`).join('')}<div class="actions"><button class="secondary" id="edit">调整信息</button><button class="primary" id="download">保存手串图片 ↓</button></div><p class="fine">此搭配是按公开规则生成的设计建议，并非唯一或客观最优答案。</p>`;$('#edit').onclick=()=>show('birth');$('#download').onclick=download;updatePreview();}
const sprite=new Image();sprite.src='assets/beads.png';sprite.onload=()=>{ $('#artStatus').hidden=true;draw()};sprite.onerror=()=>{$('#artStatus').textContent='珠材示意图暂不可用，请刷新重试'};
function draw(){const canvas=$('#bracelet'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,900,900);if(!sprite.complete||!sprite.naturalWidth)return;const ids=[];state.recipe.forEach(r=>{for(let i=0;i<r.n;i++)ids.push(r.id)});const n=ids.length,radius=295,size=Math.min(130,2*Math.PI*radius/n*1.2);ids.forEach((id,i)=>{const a=-Math.PI/2+i/n*Math.PI*2,x=450+Math.cos(a)*radius,y=450+Math.sin(a)*radius;const sw=sprite.naturalWidth/4,sh=sprite.naturalHeight/4;ctx.save();ctx.shadowColor='#0007';ctx.shadowBlur=14;ctx.shadowOffsetY=9;ctx.drawImage(sprite,id%4*sw,Math.floor(id/4)*sh,sw,sh,x-size/2,y-size/2,size,size);ctx.restore()});}
function updatePreview(){$('#previewTag').textContent=state.result?'你的专属配方':'灵感搭配';$('#designName').textContent=state.result?(state.answers[5]?'向光 · 生长':'静谧 · 自在'):'静谧 · 微光';$('#beadSpec').textContent=`${state.recipe.reduce((s,r)=>s+r.n,0)} 颗 / ${state.birth.size} mm`;$('#legend').innerHTML=state.recipe.map(r=>`<span><i style="background:${crystals[r.id].hex}"></i>${crystals[r.id].name} ${r.n}</span>`).join('');$('#previewNote').textContent=state.result?'按当前配方渲染 · AI 材质示意，非实物照片':'示例搭配。完成探索后，为你生成专属配方。';draw()}
function download(){if(!sprite.naturalWidth){alert('珠材图片还未加载，请稍后再试。');return}const c=document.createElement('canvas');c.width=1200;c.height=1450;const ctx=c.getContext('2d');ctx.fillStyle='#172425';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage($('#bracelet'),100,120,1000,1000);ctx.textAlign='center';ctx.fillStyle='#d8ba80';ctx.font='34px serif';ctx.fillText('晶遇 · '+$('#designName').textContent,600,100);ctx.fillStyle='#f1efe7';ctx.font='27px sans-serif';ctx.fillText(state.recipe.map(r=>`${crystals[r.id].name} ${r.n}颗`).join('  ·  '),600,1210);ctx.font='22px sans-serif';ctx.fillText($('#beadSpec').textContent+' · 手围 '+state.birth.wrist+' cm',600,1265);ctx.fillStyle='#a2b0ab';ctx.font='19px sans-serif';ctx.fillText('AI 材质示意 · 文化寓意与个人审美参考',600,1350);const a=document.createElement('a');a.download='晶遇-专属手串.png';a.href=c.toDataURL('image/png');a.click()}
function library(filter='全部'){const choices=['全部','木','火','土','金','水'];$('#filters').innerHTML=choices.map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}">${f}</button>`).join('');$('#catalog').innerHTML=crystals.filter(c=>filter==='全部'||c.element===filter).map(c=>`<button class="crystal-card" data-id="${c.id}">${bead(c.id)}<h3>${c.name}</h3><p>${c.element} · ${c.color} / ${c.meaning}</p></button>`).join('');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>library(b.dataset.filter));document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{const c=crystals[+b.dataset.id];$('#detailBody').innerHTML=`${bead(c.id)}<p class="eyebrow">CRYSTAL NO. ${String(c.id+1).padStart(2,'0')}</p><h2>${c.name}</h2><p>${c.texture}</p><p>颜色：${c.color} · 五行配色：${c.element}<br>设计寓意：${c.meaning}<br>支持珠径：6 / 8 / 10 / 12 mm</p><p>可作为主石、辅石或点缀石。寓意用于个人审美表达，不代表晶石具有改变性格或运势的功效。</p>`;$('#detail').showModal()})}
$('#libraryTop').onclick=()=>{$('#library').hidden=false;library();$('#library').scrollIntoView({behavior:'smooth'})};$('#closeLibrary').onclick=()=>{$('#library').hidden=true;window.scrollTo({top:0,behavior:'smooth'})};$('#closeDetail').onclick=()=>$('#detail').close();document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));renderQuiz();updatePreview();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_crystal_recipe',description:'读取当前手串配方与完成状态，不改变页面。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('参数必须为空对象');return {completed:state.result,beads:state.recipe.map(r=>({name:crystals[r.id].name,count:r.n})),diameter:state.birth.size}}})).catch(()=>{})}catch{}}
